CREATE TABLE schema_version(version INTEGER PRIMARY KEY CHECK(version=1),backend TEXT NOT NULL CHECK(backend='sqlite'),checksum TEXT NOT NULL) STRICT;
CREATE TABLE organization(id TEXT PRIMARY KEY,timezone TEXT NOT NULL,graph_revision INTEGER NOT NULL DEFAULT 1 CHECK(graph_revision>0)) STRICT;
CREATE TABLE authorization_guard(org_id TEXT PRIMARY KEY REFERENCES organization(id),auth_epoch INTEGER NOT NULL DEFAULT 1 CHECK(auth_epoch>0)) STRICT;
CREATE TABLE subject(org_id TEXT NOT NULL REFERENCES organization(id),id TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN(0,1)),auth_epoch INTEGER NOT NULL CHECK(auth_epoch>0),PRIMARY KEY(org_id,id)) STRICT;
CREATE TABLE session(token_hash BLOB PRIMARY KEY CHECK(length(token_hash)=32),org_id TEXT NOT NULL,subject_id TEXT NOT NULL,subject_epoch INTEGER NOT NULL CHECK(subject_epoch>0),expires_at INTEGER NOT NULL,idle_expires_at INTEGER NOT NULL,mfa_until INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN(0,1)),csrf_hash BLOB NOT NULL CHECK(length(csrf_hash)=32),csrf_version INTEGER NOT NULL CHECK(csrf_version>0),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id)) STRICT;
CREATE TABLE employee(org_id TEXT NOT NULL REFERENCES organization(id),id TEXT NOT NULL,profile_head_id TEXT NOT NULL,profile_revision INTEGER NOT NULL CHECK(profile_revision>0),valid_from TEXT NOT NULL CHECK(length(valid_from)=10 AND date(valid_from) IS NOT NULL AND date(valid_from)=valid_from),valid_to TEXT CHECK(valid_to IS NULL OR (length(valid_to)=10 AND date(valid_to) IS NOT NULL AND date(valid_to)=valid_to AND valid_from<valid_to)),PRIMARY KEY(org_id,id),UNIQUE(id),FOREIGN KEY(org_id,id,profile_head_id) REFERENCES employee_profile_version(org_id,employee_id,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE capability_assignment(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,capability TEXT NOT NULL CHECK(capability IN('organization.read','organization.write','pii.read','pii.write')),scope_kind TEXT NOT NULL CHECK(scope_kind IN('org','employee')),scope_id TEXT NOT NULL,employee_id TEXT,PRIMARY KEY(org_id,subject_id,capability,scope_kind,scope_id),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),CHECK((scope_kind='org' AND scope_id=org_id AND employee_id IS NULL) OR (scope_kind='employee' AND employee_id IS NOT NULL AND scope_id=employee_id))) STRICT;
CREATE TABLE access_grant(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,subject_id TEXT NOT NULL,capability TEXT NOT NULL CHECK(capability IN('organization.read','organization.write','pii.read','pii.write')),category TEXT NOT NULL CHECK((category='metadata' AND capability IN('organization.read','organization.write')) OR (category='pii' AND capability IN('pii.read','pii.write'))),scope_kind TEXT NOT NULL CHECK(scope_kind IN('org','employee')),scope_id TEXT NOT NULL,employee_id TEXT,purpose TEXT NOT NULL CHECK(purpose='organization_management'),valid_from INTEGER NOT NULL,expires_at INTEGER NOT NULL CHECK(expires_at>valid_from),revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN(0,1)),relation_bound INTEGER NOT NULL DEFAULT 0 CHECK(relation_bound=0),mfa_required INTEGER NOT NULL DEFAULT 0 CHECK(mfa_required IN(0,1)),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),CHECK((scope_kind='org' AND scope_id=org_id AND employee_id IS NULL) OR (scope_kind='employee' AND employee_id IS NOT NULL AND scope_id=employee_id))) STRICT;
CREATE TABLE encrypted_payload(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,record_id TEXT NOT NULL CHECK(record_id=employee_id),version_id TEXT NOT NULL CHECK(version_id=id),object_kind TEXT NOT NULL CHECK(object_kind='employee_profile'),purpose TEXT NOT NULL CHECK(purpose='pii'),schema_type TEXT NOT NULL CHECK(schema_type='pii.profile.v2'),schema_version INTEGER NOT NULL CHECK(schema_version=1),format_version INTEGER NOT NULL CHECK(format_version=1),algorithm TEXT NOT NULL CHECK(algorithm='A256GCM-RANDOMNONCE'),dek_id TEXT NOT NULL,kek_id TEXT NOT NULL CHECK(length(kek_id)>0),kek_version INTEGER NOT NULL CHECK(kek_version>0),wrapped_dek BLOB NOT NULL CHECK(length(wrapped_dek)>0),sealed_bytes BLOB NOT NULL CHECK(length(sealed_bytes)>=28),created_at INTEGER NOT NULL,PRIMARY KEY(org_id,employee_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id)) STRICT;
CREATE TABLE employee_profile_version(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,version_no INTEGER NOT NULL CHECK(version_no>0),payload_id TEXT NOT NULL CHECK(payload_id=id),supersedes_id TEXT CHECK(supersedes_id IS NULL OR supersedes_id<>id),recorded_at INTEGER NOT NULL,PRIMARY KEY(org_id,employee_id,id),UNIQUE(org_id,employee_id,version_no),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,employee_id,payload_id) REFERENCES encrypted_payload(org_id,employee_id,id),FOREIGN KEY(org_id,employee_id,supersedes_id) REFERENCES employee_profile_version(org_id,employee_id,id)) STRICT;
CREATE TABLE command_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('OP-ORG-05','OP-ORG-08')),key TEXT NOT NULL,digest BLOB NOT NULL CHECK(length(digest)=32),digest_key_version INTEGER NOT NULL DEFAULT 1 CHECK(digest_key_version=1),result_id TEXT NOT NULL,result_revision INTEGER NOT NULL CHECK(result_revision>0),PRIMARY KEY(org_id,subject_id,operation,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,result_id) REFERENCES employee(org_id,id)) STRICT;
CREATE TABLE audit_event(id TEXT PRIMARY KEY,org_id TEXT REFERENCES organization(id),subject_id TEXT,employee_id TEXT,operation TEXT NOT NULL CHECK(operation IN('OP-ORG-05','OP-ORG-06','OP-ORG-08','OP-SEC-01')),purpose TEXT NOT NULL CHECK(purpose IN('organization_management','')),request_id TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('allowed','denied')),recorded_at INTEGER NOT NULL,FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),CHECK(subject_id IS NULL OR org_id IS NOT NULL),CHECK(employee_id IS NULL OR org_id IS NOT NULL),CHECK(outcome<>'denied' OR employee_id IS NULL)) STRICT;
CREATE INDEX session_subject ON session(org_id,subject_id);
CREATE INDEX assignment_employee ON capability_assignment(org_id,employee_id);
CREATE INDEX grant_subject_scope ON access_grant(org_id,subject_id,scope_kind,scope_id);
CREATE INDEX grant_employee ON access_grant(org_id,employee_id);
CREATE INDEX version_payload ON employee_profile_version(org_id,employee_id,payload_id);
CREATE INDEX version_supersedes ON employee_profile_version(org_id,employee_id,supersedes_id);
CREATE INDEX receipt_result ON command_receipt(org_id,result_id);
CREATE INDEX audit_subject ON audit_event(org_id,subject_id);
CREATE INDEX audit_employee ON audit_event(org_id,employee_id);
